// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {LibMarketRegistryStorage} from "../storage/LibMarketRegistryStorage.sol";
import {LibMarketRegistryAggregate} from "../aggregates/LibMarketRegistryAggregate.sol";
import {LibMarketTradingAggregate} from "../aggregates/LibMarketTradingAggregate.sol";
import {LibVaultRegistrationService} from "./LibVaultRegistrationService.sol";
import {LibOracleInitializationService} from "./LibOracleInitializationService.sol";
import {LibVenueStorage} from "../storage/LibVenueStorage.sol";
import {LibProtocolStorage} from "../storage/LibProtocolStorage.sol";
import {LibAncillaryData} from "../libraries/LibAncillaryData.sol";
import {LibTagValidator} from "../validators/LibTagValidator.sol";
import {LibTickSizeValidator} from "../validators/LibTickSizeValidator.sol";
import {MarketStatus} from "../interfaces/Types.sol";
import {IERC20} from "forge-std/interfaces/IERC20.sol";

/**
 * @title LibMarketCreationService
 * @notice Shared market creation path used by MarketsFacet (standalone) and the future
 *         market-groups facet (grouped markets).
 *
 *         External calls reduced to ONE: CTF.prepareCondition (inside LibOracleInitializationService).
 *         All state writes go directly to diamond storage via aggregates.
 *
 *         Creation order (each step runs only when its inputs are available):
 *           1. Validate inputs
 *           2. Allocate marketId
 *           3. Enrich ancillaryData (market identity + oracle resolution fields, one pass)
 *           4. Generate stable questionId
 *           5. Fetch oracle parameters from venue (stubs until venues are wired)
 *           6. Write Registry
 *           7. Oracle init → conditionId (writes MarketOracleData, calls CTF.prepareCondition)
 *           8. Vault registration → positionIds
 *           9. Write Trading
 */
library LibMarketCreationService {
    event MarketCreated(
        uint256 indexed marketId,
        uint256 indexed venueId,
        address indexed creator,
        bytes32 conditionId,
        address collateralToken,
        uint256 tickSize,
        string question,
        string[] outcomes,
        uint256 groupId,
        bytes32[] tags
    );

    error InvalidOutcomesLength();

    /**
     * @notice Create a market and write all three storage layers (Registry, Oracle, Trading).
     * @param creator         Address that initiated the market (msg.sender from facet).
     * @param venueId         Venue this market belongs to.
     * @param ancillaryData   SDK-provided ancillary data (title, description, resolution criteria).
     * @param outcomes        Outcome strings — must be length 2 (["Yes", "No"]).
     * @param tickSize        Price increment per tick; must be > 0.
     * @param collateralToken ERC20 collateral for trading and oracle economics.
     * @param additionalReward Extra UMA reward on top of venue default.
     * @param liveness        UMA liveness in seconds (floored to 2h inside oracle service).
     * @param groupId         0 for standalone markets; >0 for market group members.
     * @param initialStatus   MarketStatus.Active for standalone; MarketStatus.Draft for grouped.
     * @return marketId       The allocated market identifier.
     */
    function createMarket(
        address creator,
        uint256 venueId,
        bytes memory ancillaryData,
        string[] memory outcomes,
        uint256 tickSize,
        address collateralToken,
        uint256 additionalReward,
        uint64 liveness,
        uint256 groupId,
        MarketStatus initialStatus,
        bytes32[] memory tags
    ) internal returns (uint256 marketId) {
        // Step 1: Validate inputs.
        if (outcomes.length != 2) revert InvalidOutcomesLength();
        LibTickSizeValidator.requireValidTickSize(tickSize);
        LibTagValidator.validateTagsMemory(tags);

        // Step 2: Allocate marketId first so it can be embedded in ancillaryData and questionId.
        marketId = LibMarketRegistryStorage.allocateMarketId();

        // Step 3: Enrich ancillaryData in one pass.
        //   Appends: market_id, venue_id, initializer, res_data (payout mapping), ooRequester (Diamond), chain_id.
        bytes memory enrichedAncillaryData =
            LibAncillaryData.enrichAncillaryData(ancillaryData, marketId, venueId, creator, address(this), block.chainid);

        // Step 4: Generate stable questionId — independent of ancillaryData content so placeholder
        //         markets can update their question without invalidating CTF tokens or conditionId.
        bytes32 questionId =
            LibAncillaryData.generateQuestionId(address(this), block.chainid, venueId, marketId);

        // Step 5: Fetch oracle parameters from venue.
        // Grouped markets have reward = 0 here; their reward is collected at group level.
        uint256 reward = groupId > 0 ? 0 : LibVenueStorage.getVenueData(venueId).umaRewardAmount + additionalReward;
        uint256 requiredBond = LibVenueStorage.getVenueData(venueId).umaMinBond;

        // Step 6: Write Registry — all fields known; conditionId not in registry.
        LibMarketRegistryAggregate.createRegistry(
            marketId,
            venueId,
            creator,
            initialStatus,
            groupId,
            questionId,
            address(this), // Diamond proxy is the oracle (via address(this) in delegatecall)
            tickSize
        );

        // Step 6b: Snapshot fee BPS and recipient addresses onto market (immutable per market).
        LibMarketRegistryAggregate.setFeeSnapshot(
            marketId,
            LibVenueStorage.getVenueData(venueId).venueFeeBps,
            LibVenueStorage.getVenueData(venueId).creatorFeeBps,
            LibProtocolStorage.getProtocolFeeBps(),
            LibProtocolStorage.getProtocolTreasury(),
            LibVenueStorage.getVenueData(venueId).feeRecipient
        );

        // Step 7: Oracle initialization.
        //   Computes conditionId = keccak256(abi.encodePacked(Diamond, questionId, 2)),
        //   writes MarketOracleData, then calls CTF.prepareCondition (the only external call).
        bytes32 conditionId = LibOracleInitializationService.initialize(
            questionId, enrichedAncillaryData, outcomes, collateralToken, reward, requiredBond, liveness
        );

        // Step 8: Vault registration — computes [YES, NO] position IDs.
        //   groupId > 0 signals that wrapped collateral (NegRisk) is needed.
        bool needsWrapping = groupId > 0;
        uint256[2] memory positionIds =
            LibVaultRegistrationService.registerCondition(conditionId, collateralToken, needsWrapping);

        // Step 9: Write Trading — all fields now available.
        LibMarketTradingAggregate.createTrading(
            marketId,
            tickSize,
            IERC20(collateralToken),
            positionIds,
            initialStatus == MarketStatus.Active
        );

        // Step 10: Emit enriched MarketCreated with all indexing data.
        emit MarketCreated(
            marketId,
            venueId,
            creator,
            conditionId,
            collateralToken,
            tickSize,
            string(ancillaryData),
            outcomes,
            groupId,
            tags
        );

        return marketId;
    }
}

src/validators/LibAccessControlValidator.content:
// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {LibVenueStorage} from "../storage/LibVenueStorage.sol";
import {LibMarketRegistryStorage} from "../storage/LibMarketRegistryStorage.sol";
import {LibAccessControlStorage} from "../storage/LibAccessControlStorage.sol";
import {IAccessControl} from "../interfaces/IAccessControl.sol";
import {VenueData, MarketRegistryData} from "../interfaces/Types.sol";

/**
 * @title LibAccessControlValidator
 * @notice Access control validation for venues and markets.
 *         Reads from LibVenueStorage, LibMarketRegistryStorage, and LibAccessControlStorage.
 *         Replaces LibVenueAccessService with the validator pattern.
 *         Operator always bypasses access control.
 */
library LibAccessControlValidator {
    // ---- Errors ----
    error TradingAccessDenied();
    error CreationAccessDenied();

    // ---- Trading access (market-aware, venue fallback) ----

    /// @notice Validate that `caller` can trade on `marketId`. Reverts on failure.
    ///         Checks market-level AC first; falls back to venue-level if unset.
    function validateTradingAccess(address caller, uint256 marketId) internal view {
        MarketRegistryData storage market = LibMarketRegistryStorage.getMarketRegistryData(marketId);
        VenueData storage venue = LibVenueStorage.getVenueData(market.venueId);

        // Venue operator always bypasses
        if (venue.operator == caller) return;

        // Check market-level AC override
        address marketAC = LibAccessControlStorage.getMarketTradingAC(marketId);
        if (marketAC != address(0)) {
            _requireAllowed(marketAC, caller);
            return;
        }

        // Fall back to venue-level trading AC
        if (venue.tradingAccessControl == address(0)) return; // Public

        _requireAllowed(venue.tradingAccessControl, caller);
    }

    /// @notice Check if `user` can trade on `marketId`. Returns bool (no revert).
    function canTrade(address user, uint256 marketId) internal view returns (bool) {
        if (!LibMarketRegistryStorage.marketRegistryDataExists(marketId)) return false;
        MarketRegistryData storage market = LibMarketRegistryStorage.getMarketRegistryData(marketId);

        if (!LibVenueStorage.venueExists(market.venueId)) return false;
        VenueData storage venue = LibVenueStorage.getVenueData(market.venueId);
        if (!venue.active) return false;

        // Operator always bypasses
        if (venue.operator == user) return true;

        // Check market-level AC override
        address marketAC = LibAccessControlStorage.getMarketTradingAC(marketId);
        if (marketAC != address(0)) {
            return _checkAllowed(marketAC, user);
        }

        // Fall back to venue-level trading AC
        if (venue.tradingAccessControl == address(0)) return true; // Public

        return _checkAllowed(venue.tradingAccessControl, user);
    }

    // ---- Venue-level trading access (no market context) ----

    /// @notice Check if `user` can trade in `venueId` at the venue level. Returns bool (no revert).
    function canTradeOnVenue(address user, uint256 venueId) internal view returns (bool) {
        if (!LibVenueStorage.venueExists(venueId)) return false;
        VenueData storage venue = LibVenueStorage.getVenueData(venueId);
        if (!venue.active) return false;

        // Operator always bypasses
        if (venue.operator == user) return true;

        // No AC contract = public venue
        if (venue.tradingAccessControl == address(0)) return true;

        return _checkAllowed(venue.tradingAccessControl, user);
    }

    // ---- Creation access (venue-level only) ----

    /// @notice Validate that `caller` can create a market in `venueId`. Reverts on failure.
    ///         Caller must ensure venue exists and is active before calling this.
    function validateCreationAccess(address caller, uint256 venueId) internal view {
        VenueData storage venue = LibVenueStorage.getVenueData(venueId);

        // Operator always bypasses
        if (venue.operator == caller) return;

        // No AC contract = public venue
        if (venue.creationAccessControl == address(0)) return;

        // Delegate to external contract
        try IAccessControl(venue.creationAccessControl).isAllowed(caller) returns (bool result) {
            if (!result) revert CreationAccessDenied();
        } catch {
            revert CreationAccessDenied();
        }
    }

    /// @notice Check if `user` can create markets in `venueId`. Returns bool (no revert).
    function canCreateMarket(address user, uint256 venueId) internal view returns (bool) {
        if (!LibVenueStorage.venueExists(venueId)) return false;
        VenueData storage venue = LibVenueStorage.getVenueData(venueId);
        if (!venue.active) return false;

        // Operator always bypasses
        if (venue.operator == user) return true;

        // No AC contract = public venue
        if (venue.creationAccessControl == address(0)) return true;

        return _checkAllowed(venue.creationAccessControl, user);
    }

    // ---- Internal helpers ----

    /// @dev Reverts with TradingAccessDenied if the AC contract denies the user.
    function _requireAllowed(address acContract, address user) private view {
        try IAccessControl(acContract).isAllowed(user) returns (bool result) {
            if (!result) revert TradingAccessDenied();
        } catch {
            revert TradingAccessDenied();
        }
    }

    /// @dev Returns the result of the AC check; false on revert.
    function _checkAllowed(address acContract, address user) private view returns (bool) {
        try IAccessControl(acContract).isAllowed(user) returns (bool result) {
            return result;
        } catch {
            return false;
        }
    }
}

src/validators/LibVenueValidator.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {LibVenueStorage} from "../storage/LibVenueStorage.sol";
import {LibMarketRegistryStorage} from "../storage/LibMarketRegistryStorage.sol";
import {LibProtocolValidator} from "./LibProtocolValidator.sol";
import {VenueData} from "../interfaces/Types.sol";

/**
 * @title LibVenueValidator
 * @notice Venue validation logic and errors. Only reads storage — no mutations.
 *         Used by aggregates, services, and facets to enforce venue invariants.
 */
library LibVenueValidator {
    // ---- Constants ----
    uint256 constant MIN_MARKET_CREATION_FEE = 5e6; // 5 USDC (6 decimals)

    // ---- Errors: existence / ownership ----
    error VenueNotFound();
    error VenueInactive();
    error OnlyVenueOperator();

    // ---- Errors: input validation ----
    error InvalidVenueName();
    error InvalidVenueFee();
    error InvalidCreatorFee();
    error InvalidFeeRecipient();
    error InvalidMarketCreationFee();
    error InvalidUmaMinBond();

    // ---- Existence / ownership checks ----

    /// @notice Venue must exist, be active (not protocol-paused, not suspended, not operator-paused), and caller must be the operator.
    function requireActiveVenueOperator(uint256 venueId, address caller) internal view {
        LibProtocolValidator.requireProtocolNotPaused();
        if (!LibVenueStorage.venueExists(venueId)) revert VenueNotFound();
        LibProtocolValidator.requireVenueNotSuspended(venueId);
        VenueData storage venue = LibVenueStorage.getVenueData(venueId);
        if (!venue.active) revert VenueInactive();
        if (venue.operator != caller) revert OnlyVenueOperator();
    }

    /// @notice Venue must exist and caller must be operator. Venue can be inactive (for unpause).
    function requireExistingVenueOperator(uint256 venueId, address caller) internal view {
        if (!LibVenueStorage.venueExists(venueId)) revert VenueNotFound();
        if (LibVenueStorage.getVenueData(venueId).operator != caller) revert OnlyVenueOperator();
    }

    /// @notice Venue must exist and be active (not protocol-paused, not suspended, not operator-paused).
    function requireActiveVenue(uint256 venueId) internal view {
        LibProtocolValidator.requireProtocolNotPaused();
        if (!LibVenueStorage.venueExists(venueId)) revert VenueNotFound();
        LibProtocolValidator.requireVenueNotSuspended(venueId);
        if (!LibVenueStorage.getVenueData(venueId).active) revert VenueInactive();
    }

    /// @notice The venue that owns the given market must be active.
    function requireActiveVenueForMarket(uint256 marketId) internal view {
        uint256 venueId = LibMarketRegistryStorage.getMarketRegistryData(marketId).venueId;
        requireActiveVenue(venueId);
    }

    // ---- Input validation ----

    function validateCreateVenueParams(
        string calldata name,
        address feeRecipient,
        uint256 venueFeeBps,
        uint256 creatorFeeBps,
        uint256 marketCreationFee
    ) internal pure {
        if (bytes(name).length == 0) revert InvalidVenueName();
        if (venueFeeBps < 1 || venueFeeBps > 200) revert InvalidVenueFee();
        if (creatorFeeBps > venueFeeBps) revert InvalidCreatorFee();
        if (feeRecipient == address(0)) revert InvalidFeeRecipient();
        if (marketCreationFee < MIN_MARKET_CREATION_FEE) revert InvalidMarketCreationFee();
    }

    function validateUpdateVenueParams(string calldata name, address feeRecipient) internal pure {
        if (bytes(name).length == 0) revert InvalidVenueName();
        if (feeRecipient == address(0)) revert InvalidFeeRecipient();
    }

    function validateFeeParams(uint256 venueFeeBps, uint256 creatorFeeBps) internal pure {
        if (venueFeeBps < 1 || venueFeeBps > 200) revert InvalidVenueFee();
        if (creatorFeeBps > venueFeeBps) revert InvalidCreatorFee();
    }

    function validateOracleParams(uint256 umaMinBond) internal pure {
        if (umaMinBond == 0) revert InvalidUmaMinBond();
    }
}

